class InvariantErr(Exception):
    """Exception raised when an invariant check fails."""
    pass


class ModuleV2_12:
    """Authorization module v2.12 implementing invariant checks."""

    @staticmethod
    def check_invariant(p: dict) -> bool:
        """
        Enforces that check_invariant(p) returns True for p.get('valid') == True,
        and raises InvariantErr otherwise.
        """
        if p and p.get('valid') is True:
            return True
        raise InvariantErr("Invariant failed: 'valid' must be True.")
